text:
Data
Two publicly available datasets are used. Neither contains personal information, so no POPIA considerations apply.

Theewaterskloof Dam levels: the Dam levels from 2000 dataset from the City of Cape Town Open Data Portal (City of Cape Town, 2026). The variable used is THEEWATERSKLOOF_Current, the daily dam level as a percentage of full capacity, from January 2000 to January 2026.
Sea surface temperature: daily SST (°C) from the seven TAO/TRITON moored buoys along 95°W (8°N, 5°N, 2°N, 0°, 2°S, 5°S and 8°S), downloaded from the Global Tropical Moored Buoy Array data delivery page (NOAA Pacific Marine Environmental Laboratory, 2026). Days on which a buoy did not record are coded as -9.99.

Data access instructions. Both datasets are updated continuously, so the snapshots used here (accessed 30 September 2026) are saved in the _data/ folder next to this file and are included in the submitted portfolio. To download them again:

Go to https://odp-cctegis.opendata.arcgis.com/, search for “Dam levels”, open Dam levels from 2000, choose Download → CSV and save the file as _data/Dam_Levels_from_2000.csv.
Go to https://www.pmel.noaa.gov/tao/drupal/disdel/, select Sea Surface Temperature, daily resolution and ASCII format, and select the seven sites on 95°W listed above. Unzip the download into _data/; the files are named sst8n95w_dy.ascii, …, sst8s95w_dy.ascii.



Show code
# Read in data:
damlvl_dat = read_csv("_data/Dam_Levels_from_2000.csv")

# Sort data:
damlvl_ts = damlvl_dat |&gt;
  mutate(DATE = dmy(DATE)) |&gt;
  arrange(DATE) |&gt;
  distinct(DATE, .keep_all = TRUE) |&gt;
  as_tsibble(index = DATE) |&gt;
  fill_gaps() # missing dates = NAs 




Show code
# Store sea surface temperature files:
sst_files = c(
  "_data/sst0n95w_dy.ascii",
  "_data/sst2n95w_dy.ascii",
  "_data/sst5n95w_dy.ascii",
  "_data/sst8n95w_dy.ascii",
  "_data/sst2s95w_dy.ascii",
  "_data/sst5s95w_dy.ascii",
  "_data/sst8s95w_dy.ascii"
)

# Function to read one buoy file:
sst_files_fxn = function(path){
  # Read raw lines:
  raw_lines  = readLines(path)

  # Extract only lines starting with a date:
  data_lines = raw_lines[grepl("^[0-9]{8}\\s", str_trim(raw_lines))]

  # Read into dataframe:
  read.table(
    text      = data_lines,
    header    = FALSE,
    col.names = c("YYYYMMDD", "HHMM", "SST", "Q", "S")
  ) |&gt;
    filter(SST != -9.99) |&gt;
    mutate(Date = as.Date(as.character(YYYYMMDD), format = "%Y%m%d")) |&gt;
    as_tsibble(index = Date) |&gt;
    fill_gaps() |&gt;
    as_tibble()
}

buoy_daily = sst_files |&gt;
  map_dfr(sst_files_fxn, .id = "station_id") |&gt;
  mutate(month = month(Date))

# Monthly climatology of each buoy and average across buoys:
buoy_clim = buoy_daily |&gt;
  filter(!is.na(SST)) |&gt;
  group_by(station_id, month) |&gt;
  summarise(clim = mean(SST), .groups = "drop")

grand_clim = buoy_clim |&gt;
  group_by(month) |&gt;
  summarise(grand_clim = mean(clim), .groups = "drop")

# Note: a plain mean jumps when a warm or cool buoy drops out
# Composition-adjusted daily mean (mean anomaly of reporting buoys + all-buoy climatology):
all_ts = buoy_daily |&gt;
  left_join(buoy_clim,  by = c("station_id", "month")) |&gt;
  left_join(grand_clim, by = "month") |&gt;
  mutate(anom = SST - clim) |&gt;
  group_by(Date) |&gt;
  summarise(
    raw_SST    = if (all(is.na(SST)))  NA_real_ else mean(SST,  na.rm = TRUE),
    mean_SST   = if (all(is.na(anom))) NA_real_ else mean(anom, na.rm = TRUE) + first(grand_clim),
    active_obs = sum(!is.na(SST)),
    .groups    = "drop"
  ) |&gt;
  as_tsibble(index = Date) |&gt;
  fill_gaps()

# Determine how many missing values exist and the length of each gap:
r = rle(is.na(all_ts$mean_SST))

threshold_days = 14                         # no. days we can smooth over
imputed_full   = na_kalman(all_ts$mean_SST) # smooth over every gap

cut_ts = all_ts |&gt;
  mutate(
    is_missing = is.na(mean_SST),
    run_len    = rep(r$lengths, r$lengths),

    # If day is missing and gap is &lt;= 14 days, smooth, else leave as NA:
    mean_SST   = if_else(is_missing & run_len &lt;= threshold_days, imputed_full, mean_SST)
  ) |&gt;
  select(-is_missing, -run_len) |&gt;
  filter(Date &gt;= as.Date("2000-01-01"))

# Effect of composition adjustment:
obs_days      = all_ts |&gt; as_tibble() |&gt; filter(!is.na(raw_SST))
pct_all_seven = mean(obs_days$active_obs == 7) * 100
max_adj_diff  = max(abs(obs_days$mean_SST - obs_days$raw_SST))




Show code
# Aggregate both series to monthly means:
monthly_damlvl_ts = damlvl_ts |&gt;
  index_by(year_month = ~ yearmonth(.)) |&gt;
  summarise(current_mean = mean(THEEWATERSKLOOF_Current, na.rm = TRUE))

monthly_ts = cut_ts |&gt;
  index_by(year_month = ~ yearmonth(.)) |&gt;
  summarise(current_mean = mean(mean_SST, na.rm = TRUE)) |&gt;
  mutate(current_mean = if_else(is.nan(current_mean), NA_real_, current_mean))

# SST before long gaps (short monthly gaps interpolated):
monthly_ts_pre2021 = monthly_ts |&gt;
  filter(year_month &lt;= yearmonth("2021 Oct")) |&gt;
  mutate(current_mean = na_interpolation(current_mean))


The duplicate observation in the dam level series was removed by keeping only the first occurrence of each date. The series contains 1 missing observation, left as NA.
For the SST dataset, the seven buoys were combined into a single daily value. Not every buoy recorded every day. Since the buoys sit at different latitudes, some are consistently warmer than others. Taking a simple average of the buoys that reported would therefore make the daily SST jump up or down whenever a warmer or cooler buoy didn’t record, even if the ocean temperature had not changed. Instead of averaging the raw temperatures, I averaged how far each reporting buoy was from its long-run average for that month (across 2000--2026). I added the long-run average for that month back to each reading to ensure that the series units remained in \(^{\circ}\text{C}\). This ensures that the daily average no longer jumps when observations are missing from a warmer or cooler buoy.
Let \(x_{b,t}\) be the SST recorded by buoy \(b\) on day \(t\), let \(m(t)\) be the calendar month of day \(t\), and let \(\bar{x}_{b,m}\) be the long-run average SST of buoy \(b\) in calendar month \(m\). If \(A_t\) is the set of buoys that reported on day \(t\) and \(n_t = |A_t|\), the daily SST is
\[
\text{SST}_t = \frac{1}{n_t} \sum_{b \in A_t} \left( x_{b,t} - \bar{x}_{b,m(t)} \right) + \frac{1}{7} \sum_{b=1}^{7} \bar{x}_{b,m(t)}.
\tag{1}\]
The first term in Equation 1 is the average difference between each reporting buoy and its usual temperature for that month. The second term is the usual temperature for that month across all seven buoys, kepping the units as \(^{\circ}\text{C}\). A missing buoy therefore no longer shifts the average. Without this correction, the daily average would have been out by as much as 3.35\(^{\circ}\text{C}\) on some days. Gaps of up to 14 days were filled with Kalman smoothing (Moritz & Bartz-Beielstein, 2017), while longer gaps were left.
The SST series has two long periods of missing observations, November 2021 to March 2023 and October 2024 to March 2025, when the entire buoy array was not recording. These gaps are too long to be filled reliably, so the SST models were fitted using only January 2000 to October 2021. Within this period, the remaining missing months (March and April 2017) were linearly interpolated. Finally, both series were aggregated to monthly means,
\[
y_j = \frac{1}{|D_j|} \sum_{t \in D_j} z_t,
\tag{2}\]
where \(D_j\) is the set of days in month \(j\) with an observation and \(z_t\) is the daily dam level or SST. This shows the seasonal pattern more clearly and smooths out daily noise.

Hidden Markov Models from first principles
All the HMM functions are in scripts/hmm-toolkit.R, so that this project and the tutorial questions in Section 2 use exactly the same code. The file contains the scaled forward and backward algorithms, local decoding, the Viterbi algorithm (Rabiner, 1989), the stationary distribution, the working-parameter transformation and matrix powers for forecasting.
Every function takes a matrix of state-dependent densities, dens[t, i] \(= p_i(x_t)\), so the same code works for Poisson, Gaussian and categorical observations. Writing \(\mathbf{P}(x) = \text{diag}(p_1(x), \dots, p_m(x))\) and \(\boldsymbol{\delta}\) for the distribution of \(C_1\), the likelihood is
\[
L_T = \boldsymbol{\delta}\mathbf{P}(x_1)\Gamma\mathbf{P}(x_2)\Gamma\cdots\Gamma\mathbf{P}(x_T)\mathbf{1}'.
\]
The forward algorithm evaluates this product recursively, \(\boldsymbol{\alpha}_t = \boldsymbol{\alpha}_{t-1}\Gamma\mathbf{P}(x_t)\), where \(\alpha_t(i) = P(x_{1:t}, C_t = i)\). The backward algorithm runs the other way, \(\boldsymbol{\beta}_t' = \Gamma\mathbf{P}(x_{t+1})\boldsymbol{\beta}_{t+1}'\), where \(\beta_t(i) = P(x_{t+1:T} \mid C_t = i)\). Because these products of small probabilities underflow, the code rescales at every step: it keeps the filtered probabilities \(\boldsymbol{\phi}_t\), with \(\phi_t(i) = P(C_t = i \mid x_{1:t})\), and adds the logs of the scaling constants \(u_t\).






The scaling constants are one-step-ahead forecast densities



Each scaling constant is \(u_t = \boldsymbol{\phi}_{t-1}\Gamma\mathbf{P}(x_t)\mathbf{1}' = p(x_t \mid x_{1:t-1})\). So \(\log L_T = \sum_t \log u_t\) is the same prediction error decomposition as for the Kalman filter in Section 2, and each \(\log u_t\) is the log score of a one-step-ahead forecast. Part B uses this to compare the HMM with GJR-GARCH out of sample.




Show code
# =============================================================================
# HMM toolkit, written from first principles (Time Series Analysis portfolio)
#
# Used by projects/project-04-analysis.qmd and section-2/section-2.qmd.
# Every function works with the matrix of state-dependent densities
# dens[t, i] = p_i(x_t), so the same code handles Poisson, Gaussian and
# categorical observations.
# =============================================================================

# Log-likelihood only (fast version, used inside optim()):
hmm_loglik = function(dens, delta, Gamma) {
  T_len = nrow(dens)
  v = delta * dens[1, ]
  ll = log(sum(v))
  phi = v / sum(v)
  if (T_len &gt; 1) {
    for (t in 2:T_len) {
      v = as.numeric(phi %*% Gamma) * dens[t, ]
      u = sum(v)
      ll = ll + log(u)
      phi = v / u
    }
  }
  ll
}

# Scaled forward algorithm: log-likelihood, log u_t, filtered probabilities and log alpha:
hmm_forward = function(dens, delta, Gamma) {
  T_len = nrow(dens)
  m = ncol(dens)
  phi_mat = matrix(NA, T_len, m)
  lu = numeric(T_len)
  for (t in 1:T_len) {
    v = if (t == 1) delta * dens[1, ] else as.numeric(phi %*% Gamma) * dens[t, ]
    u = sum(v)
    lu[t] = log(u)                # log p(x_t | x_{1:t-1})
    phi = v / u                   # P(C_t = i | x_{1:t})
    phi_mat[t, ] = phi
  }
  list(loglik = sum(lu), lu = lu, phi = phi_mat,
       lalpha = cumsum(lu) + log(phi_mat))   # log alpha_t(i)
}

# Scaled backward algorithm: log beta (Zucchini et al., 2016):
hmm_backward = function(dens, Gamma) {
  T_len = nrow(dens)
  m = ncol(dens)
  lbeta = matrix(0, T_len, m)     # log beta_T = 0
  phi = rep(1 / m, m)
  lscale = log(m)
  if (T_len &gt; 1) {
    for (t in (T_len - 1):1) {
      v = as.numeric(Gamma %*% (dens[t + 1, ] * phi))
      lbeta[t, ] = log(v) + lscale
      phi = v / sum(v)
      lscale = lscale + log(sum(v))
    }
  }
  lbeta
}

# Local decoding: P(C_t = i | x_{1:T}) = alpha_t(i) beta_t(i) / L_T:
hmm_local = function(dens, delta, Gamma) {
  fwd = hmm_forward(dens, delta, Gamma)
  lbeta = hmm_backward(dens, Gamma)
  exp(fwd$lalpha + lbeta - fwd$loglik)
}

# Global decoding with the Viterbi algorithm (log scale):
hmm_viterbi = function(dens, delta, Gamma) {
  T_len = nrow(dens)
  m = ncol(dens)
  lG = log(Gamma)
  ld = log(dens)
  xi = matrix(NA, T_len, m)
  xi[1, ] = log(delta) + ld[1, ]
  if (T_len &gt; 1) {
    for (t in 2:T_len) {
      for (j in 1:m) {
        xi[t, j] = max(xi[t - 1, ] + lG[, j]) + ld[t, j]
      }
    }
  }
  # Back-tracing:
  states = numeric(T_len)
  states[T_len] = which.max(xi[T_len, ])
  if (T_len &gt; 1) {
    for (t in (T_len - 1):1) {
      states[t] = which.max(xi[t, ] + lG[, states[t + 1]])
    }
  }
  list(states = states, xi = xi)
}

# Stationary distribution: solve delta (I - Gamma + U) = 1:
stat_dist = function(Gamma) {
  m = nrow(Gamma)
  solve(t(diag(m) - Gamma + 1), rep(1, m))
}

# Working (unconstrained) parameters -&gt; transition probability matrix:
gamma_w2n = function(w, m) {
  G = diag(m)
  G[!G] = exp(w)                  # off-diagonal elements, relative to the diagonal
  G / rowSums(G)
}

# h-step transition matrix Gamma^h:
mat_pow = function(M, h) {
  R = diag(nrow(M))
  for (i in seq_len(h)) R = R %*% M
  R
}


The parameters are estimated on an unconstrained “working” scale, as in the notes, so that optim() and nlm() can be used without constraints. Each off-diagonal transition probability is \(\exp(w)\) relative to 1 on the diagonal, and each row is divided by its sum (a multinomial logit), so the rows always sum to one. Poisson rates and standard deviations are estimated on the log scale.
